function oll-scan {
    Write-Host "`nOLL LEVELS SCAN - All 90 Ollama Performance Tiers" -ForegroundColor Cyan
    Write-Host ("=" * 100) -ForegroundColor DarkGray
    Write-Host ("{0,-6} {1,-10} {2,-10} {3,-10} {4,-10} {5,-10} {6,-20}" -f "Level","Context","GPU_Layers","Overhead","Parallel","KV_Cache","Model") -ForegroundColor Yellow
    Write-Host ("-" * 100) -ForegroundColor DarkGray
    1..90 | ForEach-Object {
        $fn = (Get-Content "Function:\oll$_") -join "`n"
        $ctx = if ($fn -match 'OLLAMA_CONTEXT_LENGTH="(\d+)"') { $Matches[1] } else { "?" }
        $layers = if ($fn -match 'OLLAMA_GPU_LAYERS="(\d+)"') { $Matches[1] } else { "?" }
        $overhead = if ($fn -match 'OLLAMA_GPU_OVERHEAD="(\d+)"') { $Matches[1] } else { "?" }
        $parallel = if ($fn -match 'OLLAMA_NUM_PARALLEL="(\d+)"') { $Matches[1] } else { "?" }
        $kv = if ($fn -match 'OLLAMA_KV_CACHE_TYPE="([^"]+)"') { $Matches[1] } else { "?" }
        $model = if ($fn -match 'claude --model (\S+)') { $Matches[1] } else { "?" }
        Write-Host ("{0,-6} {1,-10} {2,-10} {3,-10} {4,-10} {5,-10} {6,-20}" -f "oll$_",$ctx,$layers,$overhead,$parallel,$kv,$model)
    }
    Write-Host ("=" * 100) -ForegroundColor DarkGray
    Write-Host "All levels use --dangerously-skip-permissions for full tool access." -ForegroundColor Green
}

if ($MyInvocation.InvocationName -ne '.') {
